"""Load configuration from files and strings."""

import os

from miniconf.errors import ConfigError
from miniconf.parser import parse_lines

INCLUDE_DIRECTIVE = "@include"


def _read_lines(path):
    with open(path, "r", encoding="utf-8") as fh:
        return fh.read().splitlines()


def _include_target(line):
    """Return the include path if ``line`` is an ``@include`` directive, else None."""
    parts = line.strip().split(None, 1)
    if not parts or parts[0] != INCLUDE_DIRECTIVE:
        return None
    if len(parts) < 2 or not parts[1].strip():
        raise ConfigError("@include directive requires a path")
    return parts[1].strip()


def _expand(lines, path, stack):
    base_dir = os.path.dirname(path)
    expanded = []
    for raw in lines:
        target = _include_target(raw)
        if target is None:
            expanded.append(raw)
            continue
        include_path = os.path.join(base_dir, os.path.expanduser(target))
        real = os.path.realpath(include_path)
        if real in stack:
            raise ConfigError(
                "include cycle detected: {} (from {})".format(include_path, path)
            )
        try:
            included = _read_lines(include_path)
        except FileNotFoundError:
            raise ConfigError(
                "included file not found: {} (from {})".format(include_path, path)
            )
        except IsADirectoryError:
            raise ConfigError(
                "included path is a directory: {} (from {})".format(include_path, path)
            )
        stack.append(real)
        try:
            expanded.extend(_expand(included, include_path, stack))
        finally:
            stack.pop()
    return expanded


def load(path):
    """Read and parse the configuration file at ``path``.

    ``@include <path>`` lines are replaced in place by the contents of the
    referenced file, resolved relative to the including file's directory.
    """
    lines = _read_lines(path)
    lines = _expand(lines, path, [os.path.realpath(path)])
    return parse_lines(lines)


def loads(text):
    """Parse configuration from a string."""
    return parse_lines(text.splitlines())
